  "content": "1|import type { DesignerVersionRecord, DesignerVersionSummary } from '../../../shared/api/queries/component-designer';
2|import {
3|  ADMIN_PAGE_BUILT_IN_BY_ID,
4|  ADMIN_PAGE_BUILT_INS,
5|  type AdminPageBuiltInId,
6|} from './adminPageTemplates';
7|import {
8|  NEW_LAYOUT_PRESETS,
9|  createStableStateFromNewLayoutPreset,
10|} from './newLayoutPresets';
11|import type { NewLayoutPresetId } from './types';
12|import { createStableStateFromTemplateSeeds } from './templateStateBuilder';
13|import { isSystemManagedShellLayoutDraft } from '../lib/shellDesignerDraft';
14|import { normalizeDesignerComponentName } from '../utils/componentName';
15|import { normalizeComponentFolder } from '../utils/componentFolder';
16|import { parseDesignerComponentPath } from '../lib/designerDraftPath';
17|
18|const BUILT_IN_COMPONENT_EPOCH = '2024-01-01T00:00:00.000Z';
19|const BUILT_IN_COMPONENT_PREFIX = 'builtin-';
20|const BUILT_IN_ADMIN_PAGE_PREFIX = 'builtin-page-';
21|
22|export const isBuiltInComponentId = (componentId: string): boolean => componentId.startsWith(BUILT_IN_COMPONENT_PREFIX);
23|
24|export const toBuiltInComponentId = (presetId: NewLayoutPresetId): string => `${BUILT_IN_COMPONENT_PREFIX}${presetId}`;
25|
26|export const toBuiltInAdminPageId = (pageId: AdminPageBuiltInId): string => `${BUILT_IN_ADMIN_PAGE_PREFIX}${pageId}`;
27|
28|export const getBuiltInPresetId = (componentId: string): NewLayoutPresetId | null => {
29|  if (!isBuiltInComponentId(componentId) || componentId.startsWith(BUILT_IN_ADMIN_PAGE_PREFIX)) {
30|    return null;
31|  }
32|
33|  const presetId = componentId.slice(BUILT_IN_COMPONENT_PREFIX.length) as NewLayoutPresetId;
34|  return NEW_LAYOUT_PRESETS.some((preset) => preset.id === presetId) ? presetId : null;
35|};
36|
37|export const getBuiltInAdminPageId = (componentId: string): AdminPageBuiltInId | null => {
38|  if (!componentId.startsWith(BUILT_IN_ADMIN_PAGE_PREFIX)) {
39|    return null;
40|  }
41|
42|  const pageId = componentId.slice(BUILT_IN_ADMIN_PAGE_PREFIX.length) as AdminPageBuiltInId;
43|  return ADMIN_PAGE_BUILT_IN_BY_ID.has(pageId) ? pageId : null;
44|};
45|
46|const listLayoutPresetSummaries = (): DesignerVersionSummary[] => (
47|  NEW_LAYOUT_PRESETS
48|    .filter((preset) => preset.id !== 'blank')
49|    .map((preset) => ({
50|      id: toBuiltInComponentId(preset.id),
51|      name: preset.id,
52|      folder: preset.category,
53|      createdAt: BUILT_IN_COMPONENT_EPOCH,
54|      updatedAt: BUILT_IN_COMPONENT_EPOCH,
55|      createdBy: 'system',
56|      updatedBy: 'system',
57|      isBuiltIn: true,
58|    }))
59|);
60|
61|const listAdminPageSummaries = (): DesignerVersionSummary[] => (
62|  ADMIN_PAGE_BUILT_INS.map((page) => ({
63|    id: toBuiltInAdminPageId(page.id),
64|    name: page.name,
65|    folder: page.folder,
66|    createdAt: BUILT_IN_COMPONENT_EPOCH,
67|    updatedAt: BUILT_IN_COMPONENT_EPOCH,
68|    createdBy: 'system',
69|    updatedBy: 'system',
70|    isBuiltIn: true,
71|  }))
72|);
73|
74|export const listBuiltInComponentSummaries = (): DesignerVersionSummary[] => (
75|  [...listAdminPageSummaries(), ...listLayoutPresetSummaries()]
76|);
77|
78|export const getBuiltInComponentRecord = (componentId: string): DesignerVersionRecord | null => {
79|  const adminPageId = getBuiltInAdminPageId(componentId);
80|  if (adminPageId) {
81|    const page = ADMIN_PAGE_BUILT_IN_BY_ID.get(adminPageId);
82|    if (!page) {
83|      return null;
84|    }
85|
86|    const { state } = createStableStateFromTemplateSeeds(page.template, componentId, page.name);
87|    return {
88|      id: componentId,
89|      name: page.name,
90|      folder: page.folder,
91|      document: state.document,
92|      bindingDefinitions: state.bindingDefinitions,
93|      metadata: {
94|        createdAt: BUILT_IN_COMPONENT_EPOCH,
95|        updatedAt: BUILT_IN_COMPONENT_EPOCH,
96|        createdBy: 'system',
97|        updatedBy: 'system',
98|      },
99|    };
100|  }
101|
102|  const presetId = getBuiltInPresetId(componentId);
103|  if (!presetId) {
104|    return null;
105|  }
106|
107|  const preset = NEW_LAYOUT_PRESETS.find((item) => item.id === presetId);
108|  if (!preset) {
109|    return null;
110|  }
111|
112|  const { state } = createStableStateFromNewLayoutPreset(presetId, componentId, preset.id);
113|
114|  return {
115|    id: componentId,
116|    name: preset.id,
117|    folder: preset.category,
118|    document: state.document,
119|    bindingDefinitions: state.bindingDefinitions,
120|    metadata: {
121|      createdAt: BUILT_IN_COMPONENT_EPOCH,
122|      updatedAt: BUILT_IN_COMPONENT_EPOCH,
123|      createdBy: 'system',
124|      updatedBy: 'system',
125|    },
126|  };
127|};
128|
129|export const getBuiltInComponentRecordByName = (componentLookup: string): DesignerVersionRecord | null => {
130|  const trimmed = componentLookup.trim();
131|  if (!trimmed) {
132|    return null;
133|  }
134|
135|  const parsedPath = parseDesignerComponentPath(trimmed);
136|  if (parsedPath) {
137|    const folderKey = normalizeComponentFolder(parsedPath.folder);
138|    const nameKey = normalizeDesignerComponentName(parsedPath.componentName);
139|    const summary = listBuiltInComponentSummaries().find(
140|      (item) => normalizeComponentFolder(item.folder || 'general') === folderKey
141|        && normalizeDesignerComponentName(item.name) === nameKey,
142|    );
143|    return summary ? getBuiltInComponentRecord(summary.id) : null;
144|  }
145|
146|  const lookupKey = normalizeDesignerComponentName(trimmed);
147|  if (!lookupKey) {
148|    return null;
149|  }
150|
151|  const summary = listBuiltInComponentSummaries().find(
152|    (item) => normalizeDesignerComponentName(item.name) === lookupKey,
153|  );
154|
155|  return summary ? getBuiltInComponentRecord(summary.id) : null;
156|};
157|
158|export const mergeComponentsCatalog = (
159|  customItems: DesignerVersionSummary[],
160|): DesignerVersionSummary[] => {
161|  const customOnly = customItems.filter(
162|    (item) => !item.isBuiltIn && !isSystemManagedShellLayoutDraft(item),
163|  );
164|  const customIds = new Set(customOnly.map((item) => item.id));
165|  const builtInItems = listBuiltInComponentSummaries().filter((item) => !customIds.has(item.id));
166|  const normalizedCustomItems = customOnly.map((item) => ({
167|    ...item,
168|    folder: item.folder?.trim() ? item.folder.trim().toLowerCase() : 'general',
169|    isBuiltIn: false,
170|  }));
171|
172|  return [...builtInItems, ...normalizedCustomItems].sort((left, right) => {
173|    const byUpdatedAt = (right.updatedAt ?? '').localeCompare(left.updatedAt ?? '');
174|    if (byUpdatedAt !== 0) {
175|      return byUpdatedAt;
176|    }
177|
178|    return left.id.localeCompare(right.id);
179|  });
180|};
181|"
}
